    index_document = "%s/%s" % (path.rstrip("/"), path_suffix)
    try:
        return respond_with_key(status_code=200, key=index_document)
    except ClientError:
        error_document = website_config.get("ErrorDocument", {}).get("Key", "").lstrip("/")
